it('answers UNSUPPORTED when disabled or incapable, and SERVER_ERROR when listFor rejects', async () => {
  const defaultHistoryReply = await askOnceEngine({
    store: new InMemorySessionStore(),
    transport: {port: 0, resume: {enabled: true}},
  });
  const explicitOffReply = await askOnceEngine({
    store: new InMemorySessionStore(),
    transport: {port: 0, resume: {enabled: true}, history: {enabled: false}},
  });
  const captured = captureLogs();
  setLogger(captured.logger);
  let startupWarned = false;
  let fiveMemberReply: {sessionId: string; frames: WireFrame[]};
  let bareMongoReply: {sessionId: string; frames: WireFrame[]};
  let failingStoreReply: {sessionId: string; frames: WireFrame[]};
  try {
    const {url: fiveMemberUrl} = await startConversationEngine({
      store: fiveMemberSessionStore(),
      transport: {port: 0, history: {enabled: true}},
